#!/usr/bin/env bash\nset -euo pipefail\n\n# Arguments\ncommit_message="$1"\nemoji_input="${2:-}"\n\n# Determine which emoji to use\nif [[ -n "$emoji_input" ]]; then\n  emoji="$emoji_input"\nelse\n  # Deterministic default for reproducible tests\n  emoji="🚀"\nfi\n\nenhanced_message="${commit_message} ${emoji}"\n\n# Write output – if GITHUB_OUTPUT is set (real Action), use it; otherwise just echo for local testing\noutput_file="${GITHUB_OUTPUT:-/dev/null}"\n\necho "enhanced_message=${enhanced_message}" >> "$output_file"\n\n# Also echo to stdout for local visibility\necho "enhanced_message=${enhanced_message}"\n
